from colorama import Fore, Stylefrom time import sleepprint('=_=_' * 12)t =int(input(Fore.LIGHTWHITE_EX + 'Deseja a tabuada de qual número? ' + Style.RESET_ALL))print('=_=_' * 12)print(Fore.GREEN + 'PROCESSANDO...' + Style.RESET_ALL)sleep(0.5)print('=_=_' * 11)sleep(0.1)print('=_=_' * 10)sleep(0.1)print('=_=_' * 9)sleep(0.1)print('=_=_' * 7)sleep(0.1)print('=_=_' * 4)sleep(0.1)print('=_=_' * 1)print(Fore.LIGHTWHITE_EX + f'a tabuada de {t} é:' + Style.RESET_ALL)for c in range (1,11):    print(Fore.LIGHTMAGENTA_EX + '{} x {} = {}' .format(t, c, t*c) + Style.RESET_ALL)